"use client"

import { useState } from "react"
import {
  AlertTriangle, ChevronDown, Filter,
  Loader2, Search,
} from "lucide-react"
import { Button }       from "@/components/ui/button"
import { Input }        from "@/components/ui/input"
import { Badge }        from "@/components/ui/badge"
import { Switch }       from "@/components/ui/switch"
import { Label }        from "@/components/ui/label"
import {
  DropdownMenu, DropdownMenuContent,
  DropdownMenuRadioGroup, DropdownMenuRadioItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { AlertMessage } from "@/components/alert-message"
import { cn }           from "@/lib/utils"
import { ApiError }     from "@/lib/api"
import { useApiError }  from "@/lib/hooks/useApiError"

// ── Types ─────────────────────────────────────────────────────────────────────

interface SearchResult {
  id:          number
  chat_id:     number
  text:        string
  is_negative: boolean
  reason:      'keyword_match' | 'ai_sentiment' | null
  confidence:  number
  sender_id:   number | null
  analyzed_at: string | null
}

interface SearchResponse {
  results: SearchResult[]
  count:   number
  query:   string
}

interface SearchContentProps {
  initialPhone: string
}

// ── Constants ─────────────────────────────────────────────────────────────────

const LIMIT_OPTIONS = [
  { value: 20,  label: "20 ta natija"  },
  { value: 50,  label: "50 ta natija"  },
  { value: 100, label: "100 ta natija" },
]

// ── Component ─────────────────────────────────────────────────────────────────

export function SearchContent({ initialPhone }: SearchContentProps) {
  const { handleError } = useApiError()

  const [query, setQuery]               = useState("")
  const [chatId, setChatId]             = useState("")
  const [negativeOnly, setNegativeOnly] = useState(true)
  const [limit, setLimit]               = useState(50)
  const [loading, setLoading]           = useState(false)
  const [error, setError]               = useState<string | null>(null)
  const [results, setResults]           = useState<SearchResponse | null>(null)

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault()
    const trimmed = query.trim()
    if (trimmed.length < 2) return

    setLoading(true)
    setError(null)
    setResults(null)

    try {
      const body: Record<string, unknown> = {
        phone:         initialPhone,
        query:         trimmed,
        negative_only: negativeOnly,
        limit,
      }

      // Chat ID is optional; Telegram IDs can be negative (supergroups)
      const parsedChatId = parseInt(chatId.trim(), 10)
      if (chatId.trim() && !isNaN(parsedChatId)) {
        body.chat_id = parsedChatId
      }

      const res = await fetch('/api/search', {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify(body),
      })

      if (!res.ok) {
        const errData = await res.json().catch(() => ({ detail: res.statusText }))
        throw new ApiError(res.status, errData.detail || res.statusText)
      }

      setResults(await res.json())
    } catch (err: unknown) {
      setError(await handleError(err))
    } finally {
      setLoading(false)
    }
  }

  // ── Render ────────────────────────────────────────────────────────────────────
  return (
    <div className="min-h-screen bg-background pt-20 pb-12">
      <div className="mx-auto max-w-4xl px-4 sm:px-6 lg:px-8">

        {/* ── Page header ─────────────────────────────────────────────────── */}
        <div className="mb-8">
          <h1 className="text-2xl font-bold text-foreground">Xabar qidiruvi</h1>
          <p className="mt-1 text-sm text-muted-foreground">
            Ilgari tahlil qilingan xabarlar orasidan qidiring
          </p>
        </div>

        {/* ── Search form ─────────────────────────────────────────────────── */}
        <form onSubmit={handleSearch}
          className="rounded-2xl border border-border/40 bg-card p-5 mb-6 space-y-3">

          {/* Row 1 — main keyword input */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              type="text"
              placeholder="Kalit so'z kiriting (kamida 2 belgi)..."
              value={query}
              onChange={e => setQuery(e.target.value)}
              className="pl-10 h-11"
              minLength={2}
              autoComplete="off"
            />
          </div>

          {/* Row 2 — filters + button — all h-10, flex items-center */}
          <div className="flex flex-wrap items-center gap-2">

            {/* Limit dropdown */}
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  type="button"
                  variant="outline"
                  className="h-10 gap-1.5 px-3 text-sm shrink-0"
                >
                  {LIMIT_OPTIONS.find(o => o.value === limit)?.label ?? `${limit} ta`}
                  <ChevronDown className="h-3.5 w-3.5 text-muted-foreground" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start" className="w-40">
                <DropdownMenuRadioGroup
                  value={String(limit)}
                  onValueChange={v => setLimit(Number(v))}
                >
                  {LIMIT_OPTIONS.map(o => (
                    <DropdownMenuRadioItem key={o.value} value={String(o.value)}>
                      {o.label}
                    </DropdownMenuRadioItem>
                  ))}
                </DropdownMenuRadioGroup>
              </DropdownMenuContent>
            </DropdownMenu>

            {/* Chat ID — text input, numeric keyboard, no "0" default */}
            <div className="flex-1 min-w-[130px]">
              <Input
                type="text"
                inputMode="numeric"
                pattern="[0-9\-]*"
                placeholder="Chat ID (ixtiyoriy)"
                value={chatId}
                onChange={e => {
                  // Allow digits and leading minus sign only
                  const v = e.target.value.replace(/[^0-9\-]/g, "")
                  setChatId(v)
                }}
                className="h-10 w-full"
              />
            </div>

            {/* "Faqat negativ" switch — boxed, same height */}
            <div className="flex items-center gap-2 h-10 px-3 rounded-lg border border-border/40
                            bg-background shrink-0 cursor-pointer"
              onClick={() => setNegativeOnly(v => !v)}
            >
              <Switch
                id="negative-only"
                checked={negativeOnly}
                onCheckedChange={setNegativeOnly}
              />
              <Label
                htmlFor="negative-only"
                className="text-sm text-muted-foreground cursor-pointer select-none whitespace-nowrap"
              >
                Faqat negativ
              </Label>
            </div>

            {/* Search button — wider, icon + text */}
            <Button
              type="submit"
              disabled={loading || query.trim().length < 2}
              className="h-10 px-6 gap-2 shrink-0 min-w-[130px] sm:w-auto w-full"
            >
              {loading ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Search className="h-4 w-4" />
              )}
              <span>{loading ? "Qidirilmoqda..." : "Qidirish"}</span>
            </Button>
          </div>
        </form>

        {error && (
          <AlertMessage
            type="error"
            message={error}
            onClose={() => setError(null)}
            className="mb-6"
          />
        )}

        {/* ── Results ─────────────────────────────────────────────────────── */}
        {results && (
          <div>
            <div className="flex items-center gap-2 mb-4">
              <Filter className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">
                <span className="font-semibold text-foreground">{results.count}</span> ta natija
                topildi —{" "}
                <span className="font-medium text-foreground">&quot;{results.query}&quot;</span>
              </span>
            </div>

            {results.results.length === 0 ? (
              <div className="rounded-2xl border border-border/40 bg-card p-12 text-center">
                <Search className="mx-auto h-12 w-12 text-muted-foreground/40" />
                <p className="mt-4 text-muted-foreground">
                  Hech narsa topilmadi. Boshqa kalit so&apos;z kiriting yoki avval chatni tahlil qiling.
                </p>
              </div>
            ) : (
              <div className="space-y-3">
                {results.results.map((item, idx) => (
                  <div
                    key={`${item.id}-${idx}`}
                    className={cn(
                      "rounded-xl border p-4",
                      item.is_negative
                        ? "border-red-500/20 bg-red-500/5"
                        : "border-border/40 bg-card"
                    )}
                  >
                    <div className="flex items-start gap-3">
                      {item.is_negative && (
                        <AlertTriangle className="h-4 w-4 text-red-400 shrink-0 mt-0.5" />
                      )}
                      <div className="flex-1 min-w-0">
                        <div className="flex flex-wrap items-center gap-2 mb-2">
                          {item.reason === 'keyword_match' && (
                            <Badge variant="secondary"
                              className="bg-blue-500/10 text-blue-600 border-blue-500/20">
                              Lug&apos;at
                            </Badge>
                          )}
                          {item.reason === 'ai_sentiment' && (
                            <Badge variant="secondary"
                              className="bg-purple-500/10 text-purple-600 border-purple-500/20">
                              AI Tahlili
                            </Badge>
                          )}
                          <span className="text-xs text-muted-foreground">
                            Chat {item.chat_id}
                          </span>
                          {item.analyzed_at && (
                            <span className="text-xs text-muted-foreground">
                              {new Date(item.analyzed_at).toLocaleDateString('uz-UZ')}
                            </span>
                          )}
                        </div>
                        <p className="text-sm text-foreground whitespace-pre-wrap break-words">
                          {item.text}
                        </p>
                        {item.reason === 'ai_sentiment' && item.confidence > 0 && (
                          <p className="mt-1 text-xs text-muted-foreground">
                            Ishonch: {(item.confidence * 100).toFixed(1)}%
                          </p>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}
